import { readFileSync } from 'node:fs';
import type { KindInfo, MemberStatus, NetworkGraph, SnapshotSummary } from '../src/app/model/api-types';

// The backend's committed, synthetic fixtures (generated by the C# test suite). Invented data only.
const dir = new URL('../../tests/fixtures/generated/', import.meta.url);

export interface HubFixture {
  graph: NetworkGraph;
  summary: SnapshotSummary;
  members: MemberStatus[];
}

export function hubFixture(): HubFixture {
  return JSON.parse(readFileSync(new URL('synthetic-hub.graph.json', dir), 'utf8'));
}

export function backendKinds(): KindInfo[] {
  return JSON.parse(readFileSync(new URL('kinds.json', dir), 'utf8'));
}
